import { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { siteConfig } from './config/site';
import {
  ChevronDown, Menu, X, Play, Check, Users, Target,
  RefreshCw, ChefHat, Calculator, Flame, Pill, MapPin,
  Search, Facebook, Twitter, Instagram, Youtube, ArrowRight,
  ChevronLeft, ChevronRight, Mail
} from 'lucide-react';

const { colors, credibilityStats, navItems, hero, trendingArticles,
  newsletterCTA, healthTopics, healthTools, recommendedReads,
  trustPillars, featuredPrograms, latestVideos, footer } = siteConfig;

function App() {
  const [activeDropdown, setActiveDropdown] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState("Top Reads");
  const [carouselIndex, setCarouselIndex] = useState(0);
  const [email, setEmail] = useState("");
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const tickerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const ticker = tickerRef.current;
    if (!ticker) return;
    let animationId: number;
    let scrollPos = 0;

    const animate = () => {
      scrollPos += 1;
      if (scrollPos >= ticker.scrollWidth / 2) {
        scrollPos = 0;
      }
      ticker.scrollLeft = scrollPos;
      animationId = requestAnimationFrame(animate);
    };

    animationId = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(animationId);
  }, []);

  const getIcon = (name: string) => {
    const icons: Record<string, JSX.Element> = {
      Users: <Users className="w-6 h-6" />,
      Target: <Target className="w-6 h-6" />,
      CheckCircle: <Check className="w-6 h-6" />,
      RefreshCw: <RefreshCw className="w-6 h-6" />,
      ChefHat: <ChefHat className="w-8 h-8" />,
      Calculator: <Calculator className="w-8 h-8" />,
      Flame: <Flame className="w-8 h-8" />,
      Pill: <Pill className="w-8 h-8" />,
      MapPin: <MapPin className="w-8 h-8" />,
      Search: <Search className="w-8 h-8" />,
      Facebook: <Facebook className="w-5 h-5" />,
      Twitter: <Twitter className="w-5 h-5" />,
      Instagram: <Instagram className="w-5 h-5" />,
      Youtube: <Youtube className="w-5 h-5" />,
    };
    return icons[name] || <Check className="w-6 h-6" />;
  };

  const handleNewsletterSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    alert(`Thank you for subscribing with: ${email}`);
    setEmail("");
  };

  const scrollTopics = (direction: 'left' | 'right') => {
    const newIndex = direction === 'left'
      ? Math.max(0, carouselIndex - 1)
      : Math.min(healthTopics.length - 3, carouselIndex + 1);
    setCarouselIndex(newIndex);
  };

  return (
    <div className="min-h-screen bg-[#FAFBFC]">
      {/* Credibility Stats Ticker */}
      <div className="bg-[#02838D] text-white py-2 overflow-hidden">
        <div
          ref={tickerRef}
          className="flex whitespace-nowrap"
          style={{ width: 'max-content' }}
        >
          {[...credibilityStats, ...credibilityStats].map((stat, i) => (
            <span key={i} className="mx-8 flex items-center gap-2 text-sm font-medium">
              <Check className="w-4 h-4 text-[#E07A5F]" />
              {stat}
            </span>
          ))}
        </div>
      </div>

      {/* Header Navigation */}
      <header className="bg-white shadow-sm sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4">
          <div className="flex items-center justify-between h-16">
            {/* Logo */}
            <div className="flex items-center gap-2">
              <div className="w-10 h-10 rounded-lg bg-[#02838D] flex items-center justify-center">
                <span className="text-white font-bold text-xl">W</span>
              </div>
              <span className="text-xl font-bold text-[#231F20]">WellSource</span>
            </div>

            {/* Desktop Nav */}
            <nav className="hidden lg:flex items-center gap-1">
              {navItems.map((item) => (
                <div key={item.label} className="relative">
                  <button
                    onMouseEnter={() => setActiveDropdown(item.label)}
                    onMouseLeave={() => setActiveDropdown(null)}
                    className="px-4 py-2 text-[#231F20] font-medium text-sm flex items-center gap-1 hover:text-[#02838D] transition-colors"
                  >
                    {item.label}
                    {item.hasDropdown && <ChevronDown className="w-4 h-4" />}
                  </button>

                  {/* Mega Menu Dropdown */}
                  <AnimatePresence>
                    {activeDropdown === item.label && item.hasDropdown && (
                      <motion.div
                        initial={{ opacity: 0, y: 10 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: 10 }}
                        transition={{ duration: 0.2 }}
                        onMouseEnter={() => setActiveDropdown(item.label)}
                        onMouseLeave={() => setActiveDropdown(null)}
                        className="absolute top-full left-0 mt-2 w-[280px] bg-white rounded-xl shadow-xl border border-gray-100 p-4"
                      >
                        <div className="grid grid-cols-2 gap-2">
                          {item.categories?.map((cat) => (
                            <a
                              key={cat.name}
                              href={cat.href}
                              className="px-3 py-2 text-sm text-[#231F20] hover:bg-[#f4f6f7] rounded-lg transition-colors"
                            >
                              {cat.name}
                            </a>
                          ))}
                        </div>
                        {item.subSections?.map((sub) => (
                          <div className="mt-4 pt-4 border-t border-gray-100">
                            <p className="text-xs font-semibold text-gray-500 uppercase mb-2">{sub.title}</p>
                            {sub.items.map((subItem) => (
                              <a
                                key={subItem.name}
                                href={subItem.href}
                                className="block px-3 py-2 text-sm text-[#02838D] hover:bg-[#f4f6f7] rounded-lg transition-colors"
                              >
                                {subItem.name}
                              </a>
                            ))}
                          </div>
                        ))}
                      </motion.div>
                    )}
                  </AnimatePresence>
                </div>
              ))}
            </nav>

            {/* Right Actions */}
            <div className="flex items-center gap-3">
              <a href="#" className="hidden sm:block text-sm font-medium text-[#231F20] hover:text-[#02838D] transition-colors">
                Subscribe
              </a>
              <a href="#" className="hidden sm:block text-sm font-medium px-4 py-2 bg-[#02838D] text-white rounded-lg hover:bg-[#026a73] transition-colors">
                Sign In
              </a>
              <button
                onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
                className="lg:hidden p-2 text-[#231F20]"
              >
                {mobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
              </button>
            </div>
          </div>
        </div>

        {/* Mobile Menu */}
        <AnimatePresence>
          {mobileMenuOpen && (
            <motion.div
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: 'auto', opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              className="lg:hidden bg-white border-t border-gray-100 overflow-hidden"
            >
              <div className="p-4 space-y-2">
                {navItems.map((item) => (
                  <details key={item.label} className="group">
                    <summary className="flex items-center justify-between py-2 px-3 cursor-pointer hover:bg-[#f4f6f7] rounded-lg">
                      <span className="font-medium text-[#231F20]">{item.label}</span>
                      <ChevronDown className="w-4 h-4" />
                    </summary>
                    <div className="pl-4 py-2 space-y-1">
                      {item.categories?.map((cat) => (
                        <a key={cat.name} href={cat.href} className="block py-1 px-3 text-sm text-gray-600 hover:text-[#02838D]">
                          {cat.name}
                        </a>
                      ))}
                    </div>
                  </details>
                ))}
                <div className="pt-4 flex flex-col gap-2">
                  <a href="#" className="text-center py-2 px-4 border border-[#02838D] text-[#02838D] rounded-lg font-medium">Subscribe</a>
                  <a href="#" className="text-center py-2 px-4 bg-[#02838D] text-white rounded-lg font-medium">Sign In</a>
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </header>

      {/* Hero Section */}
      <section className="relative bg-gradient-to-br from-[#f4f6f7] to-white overflow-hidden">
        <div className="max-w-7xl mx-auto px-4 py-12 lg:py-20">
          <div className="grid lg:grid-cols-3 gap-8 lg:gap-12">
            {/* Main Hero Content */}
            <div className="lg:col-span-2">
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.6 }}
              >
                <span className="inline-block px-3 py-1 bg-[#02838D] text-white text-xs font-semibold rounded-full mb-4">
                  {hero.category}
                </span>
                <h1 className="text-3xl sm:text-4xl lg:text-5xl font-bold text-[#231F20] leading-tight mb-6">
                  {hero.title}
                </h1>
                <p className="text-lg text-gray-600 mb-6 max-w-2xl">
                  {hero.subtitle}
                </p>
                <div className="flex flex-wrap gap-4">
                  <a
                    href="#"
                    className="inline-flex items-center gap-2 px-6 py-3 bg-[#02838D] text-white font-semibold rounded-lg hover:bg-[#026a73] transition-colors"
                  >
                    Start Day 12 <ArrowRight className="w-4 h-4" />
                  </a>
                  <span className="inline-flex items-center gap-2 px-4 py-3 bg-white text-[#231F20] font-medium rounded-lg shadow-sm">
                    <span className="w-6 h-6 bg-[#E07A5F] text-white text-xs rounded-full flex items-center justify-center font-bold">
                      {hero.badge.charAt(0)}
                    </span>
                    {hero.badge}
                  </span>
                </div>
              </motion.div>
            </div>

            {/* Trending Sidebar */}
            <motion.div
              initial={{ opacity: 0, x: 20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.6, delay: 0.2 }}
              className="lg:col-span-1"
            >
              <div className="bg-white rounded-2xl shadow-lg p-6">
                <h3 className="text-lg font-bold text-[#231F20] mb-4">Trending Now</h3>
                <div className="space-y-4">
                  {trendingArticles.map((article, i) => (
                    <a key={i} href={article.href} className="block group">
                      <span className="inline-block px-2 py-0.5 bg-[#f4f6f7] text-[#02838D] text-xs font-medium rounded mb-1">
                        {article.category}
                      </span>
                      <p className="text-sm font-medium text-[#231F20] group-hover:text-[#02838D] transition-colors line-clamp-2">
                        {article.title}
                      </p>
                    </a>
                  ))}
                </div>
              </div>
            </motion.div>
          </div>
        </div>
      </section>

      {/* Newsletter CTA */}
      <section className="bg-[#02838D] py-16">
        <div className="max-w-3xl mx-auto px-4 text-center">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.6 }}
          >
            <Mail className="w-12 h-12 text-[#E07A5F] mx-auto mb-4" />
            <h2 className="text-2xl sm:text-3xl font-bold text-white mb-4">
              {newsletterCTA.heading}
            </h2>
            <p className="text-teal-100 mb-8 text-lg">
              {newsletterCTA.body}
            </p>
            <form onSubmit={handleNewsletterSubmit} className="flex flex-col sm:flex-row gap-3 max-w-md mx-auto">
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="Enter your email"
                required
                className="flex-1 px-4 py-3 rounded-lg text-[#231F20] placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-[#E07A5F]"
              />
              <button
                type="submit"
                className="px-6 py-3 bg-[#E07A5F] text-white font-semibold rounded-lg hover:bg-[#c9684d] transition-colors"
              >
                {newsletterCTA.cta}
              </button>
            </form>
            <p className="text-teal-200 text-sm mt-4">{newsletterCTA.privacy}</p>
          </motion.div>
        </div>
      </section>

      {/* Health Topics Carousel */}
      <section className="py-16 bg-white">
        <div className="max-w-7xl mx-auto px-4">
          <div className="flex items-center justify-between mb-8">
            <h2 className="text-2xl sm:text-3xl font-bold text-[#231F20]">Explore Health Topics</h2>
            <div className="flex gap-2">
              <button
                onClick={() => scrollTopics('left')}
                className="p-2 rounded-full bg-[#f4f6f7] hover:bg-[#e5e7eb] transition-colors disabled:opacity-50"
                disabled={carouselIndex === 0}
              >
                <ChevronLeft className="w-5 h-5 text-[#231F20]" />
              </button>
              <button
                onClick={() => scrollTopics('right')}
                className="p-2 rounded-full bg-[#f4f6f7] hover:bg-[#e5e7eb] transition-colors disabled:opacity-50"
                disabled={carouselIndex >= healthTopics.length - 3}
              >
                <ChevronRight className="w-5 h-5 text-[#231F20]" />
              </button>
            </div>
          </div>
          <div className="overflow-hidden">
            <div
              className="flex gap-6 transition-transform duration-300"
              style={{ transform: `translateX(-${carouselIndex * (280 + 24)}px)` }}
            >
              {healthTopics.map((topic, i) => (
                <motion.a
                  key={i}
                  href={topic.href}
                  initial={{ opacity: 0, y: 20 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.4, delay: i * 0.1 }}
                  className="flex-shrink-0 flex flex-col items-center group"
                >
                  <div className="w-24 h-24 rounded-full overflow-hidden ring-4 ring-[#f4f6f7] group-hover:ring-[#02838D] transition-all shadow-md">
                    <img
                      src={topic.image}
                      alt={topic.name}
                      className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-300"
                    />
                  </div>
                  <span className="mt-3 text-sm font-medium text-[#231F20] text-center group-hover:text-[#02838D] transition-colors">
                    {topic.name}
                  </span>
                </motion.a>
              ))}
            </div>
          </div>
          <div className="text-center mt-8">
            <a href="#" className="inline-flex items-center gap-2 text-[#02838D] font-semibold hover:gap-3 transition-all">
              View all topics <ArrowRight className="w-4 h-4" />
            </a>
          </div>
        </div>
      </section>

      {/* Health Tools Section */}
      <section className="py-16 bg-gradient-to-b from-[#f4f6f7] to-white">
        <div className="max-w-7xl mx-auto px-4">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            className="text-center mb-12"
          >
            <h2 className="text-2xl sm:text-3xl font-bold text-[#231F20] mb-4">
              Healthy eating, simplified
            </h2>
            <p className="text-gray-600 max-w-2xl mx-auto">
              Take charge of your nutrition with guidance on meal planning, diets, supplements, and more from our dietitians and nutritionists.
            </p>
            <a href="#" className="inline-flex items-center gap-2 mt-4 text-[#02838D] font-semibold hover:gap-3 transition-all">
              Visit Nutrition Hub <ArrowRight className="w-4 h-4" />
            </a>
          </motion.div>

          <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {healthTools.map((tool, i) => (
              <motion.a
                key={i}
                href={tool.href}
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ duration: 0.4, delay: i * 0.1 }}
                className="group bg-white rounded-2xl p-6 shadow-sm hover:shadow-lg transition-all border border-gray-100"
              >
                <div className="w-14 h-14 rounded-xl bg-[#f4f6f7] flex items-center justify-center mb-4 text-[#02838D] group-hover:bg-[#02838D] group-hover:text-white transition-colors">
                  {getIcon(tool.icon)}
                </div>
                <h3 className="text-lg font-bold text-[#231F20] mb-2">{tool.name}</h3>
                <p className="text-sm text-gray-600 mb-3">{tool.description}</p>
                {tool.cta && (
                  <span className="inline-flex items-center text-[#E07A5F] text-sm font-semibold">
                    {tool.cta} <ArrowRight className="w-4 h-4 ml-1 group-hover:translate-x-1 transition-transform" />
                  </span>
                )}
              </motion.a>
            ))}
          </div>
        </div>
      </section>

      {/* Recommended Reads */}
      <section className="py-16 bg-white">
        <div className="max-w-7xl mx-auto px-4">
          <h2 className="text-2xl sm:text-3xl font-bold text-[#231F20] mb-8">Recommended Reads</h2>

          {/* Tabs */}
          <div className="flex flex-wrap gap-2 mb-8 border-b border-gray-200 pb-4">
            {recommendedReads.tabs.map((tab) => (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`px-4 py-2 text-sm font-medium rounded-lg transition-colors ${
                  activeTab === tab
                    ? 'bg-[#02838D] text-white'
                    : 'text-gray-600 hover:bg-[#f4f6f7]'
                }`}
              >
                {tab}
              </button>
            ))}
          </div>

          {/* Articles Grid */}
