                  <span className="inline-flex items-center gap-2 px-4 py-3 bg-white text-[#231F20] font-medium rounded-lg shadow-sm">
                    <span className="w-6 h-6 bg-[#E07A5F] text-white text-xs rounded-full flex items-center justify-center font-bold">
