const fs = require('fs');
const path = require('path');

// Read the built files
const html = fs.readFileSync('dist/index.html', 'utf8');
const css = fs.readFileSync('dist/assets/index-BPIHhU49.css', 'utf8');
const js = fs.readFileSync('dist/assets/index-Q6fX52rl.js', 'utf8');

// Inline CSS
let inlineHtml = html.replace(
  '<link rel=\"stylesheet\" crossorigin href=\"/assets/index-BPIHhU49.css\">',
  '<style>' + css + '</style>'
);

// Inline JS
inlineHtml = inlineHtml.replace(
  '<script type=\"module\" crossorigin src=\"/assets/index-Q6fX52rl.js\"></script>',
  '<script type=\"module\">' + js + '</script>'
);

// Fix the favicon path
inlineHtml = inlineHtml.replace('href=\"/favicon.svg\"', 'href=\"favicon.svg\"');

// Write the standalone HTML
fs.writeFileSync('dist/index.html', inlineHtml);
console.log('Done inlining assets');
"

